}

.menu-toggle {
    background: transparent;
    border: 0;
    color: var(--color-ink);
    cursor: pointer;
    display: none;
    font-size: 22px;
    padding: 5px;
}

.sidebar {
    background: #102b50;
    bottom: 0;
    color: #d7e3f4;
    left: 0;
    overflow-y: auto;
    padding: 26px 16px;
    position: fixed;
    top: 68px;
    width: 248px;
}

.sidebar-section-label {
    color: #a9bdd7;
    display: block;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.09em;
