    color: #ffffff;
}

.button-primary:hover {
    background: var(--color-primary-dark);
    color: #ffffff;
}

.button-quiet {
    background: transparent;
    color: var(--color-primary);
    padding: 8px;
}

.button-full {
    margin-top: 8px;
    width: 100%;
}

.login-page {
    align-items: center;
    display: flex;
    justify-content: center;
    min-height: 100vh;
    padding: 24px;
}

.login-card {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    box-shadow: var(--shadow-card);
    max-width: 440px;
    padding: 38px;
    width: 100%;
}

.brand-mark {
    align-items: center;
    background: #eaf1fb;
    border-radius: 10px;
    color: var(--color-primary);
    display: flex;
    font-size: 14px;
    font-weight: 800;
    height: 42px;
    justify-content: center;
    margin-bottom: 22px;
    width: 52px;
}

.login-card > .muted {
    margin: 0 0 22px;
}

.form-stack {
    display: grid;
    gap: 10px;
}

.form-stack label {
    font-size: 13px;
    font-weight: 700;
    margin-top: 5px;
}

.form-stack input {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 7px;
    min-height: 44px;
    padding: 10px 12px;
    width: 100%;
}

.form-stack input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(35, 87, 165, 0.13);
    outline: none;
}

.alert {
    border-radius: 7px;
    font-size: 13px;
    margin: 18px 0;
    padding: 11px 13px;
}

.alert-error {
    background: #fff1f0;
    border: 1px solid #f4c7c3;
    color: var(--color-danger);
}

.login-help {
    color: var(--color-muted);
    font-size: 12px;
    margin: 20px 0 0;
    text-align: center;
}

@media (max-width: 1100px) {
    .metric-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .content-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 760px) {
    .topbar {
        height: 60px;
        padding: 0 16px;
    }

    .menu-toggle {
        display: block;
    }

    .topbar-brand {
        margin-right: auto;
        padding-left: 10px;
    }

    .topbar-user {
        gap: 5px;
    }

    .user-name {
        display: none;
    }

    .sidebar {
        bottom: auto;
        display: none;
        max-height: calc(100vh - 60px);
        position: absolute;
        top: 60px;
        width: min(290px, 85vw);
        z-index: 4;
    }

    .sidebar.is-open {
        display: block;
    }

    .main-content {
        margin-left: 0;
        min-height: calc(100vh - 60px);
        padding: 25px 16px;
    }
}

@media (max-width: 480px) {
    .metric-grid {
        gap: 12px;
        grid-template-columns: 1fr 1fr;
    }

    .metric-card {
        min-height: 132px;
        padding: 15px;
    }

    .metric-value {
        font-size: 27px;
    }

    .metric-note {
        font-size: 11px;
    }

    .panel {
        padding: 17px;
    }

    .login-card {
        padding: 28px 22px;
    }
}

