        position: absolute;
        top: 60px;
        width: min(290px, 85vw);
        z-index: 4;
    }

    .sidebar.is-open {
        display: block;
    }

    .main-content {
        margin-left: 0;
        min-height: calc(100vh - 60px);
        padding: 25px 16px;
    }

    .data-form {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
