        min-height: 132px;
        padding: 15px;
    }

    .metric-value {
        font-size: 27px;
    }

    .metric-note {
        font-size: 11px;
    }

    .panel {
        padding: 17px;
    }

    .login-card {
        padding: 28px 22px;
    }
}

