    .topbar {
        height: 60px;
        padding: 0 16px;
    }

    .menu-toggle {
        display: block;
    }

    .topbar-brand {
        margin-right: auto;
        padding-left: 10px;
    }

    .topbar-user {
        gap: 5px;
    }

    .user-name {
        display: none;
    }

