        bottom: auto;
        display: none;
        max-height: calc(100vh - 60px);
        position: absolute;
        top: 60px;
        width: min(290px, 85vw);
        z-index: 4;
    }

    .sidebar.is-open {
        display: block;
    }

    .main-content {
        margin-left: 0;
        min-height: calc(100vh - 60px);
        padding: 25px 16px;
    }

    .data-form {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .metric-grid {
        gap: 12px;
        grid-template-columns: 1fr 1fr;
    }

    .metric-card {
        min-height: 132px;
        padding: 15px;
    }

    .metric-value {
        font-size: 27px;
    }

    .metric-note {
        font-size: 11px;
    }

    .panel {
        padding: 17px;
    }

    .login-card {
        padding: 28px 22px;
    }
}

