    margin: 0;
    text-transform: uppercase;
}

.muted,
.metric-note {
    color: var(--color-muted);
}

.page-heading .muted,
.panel-heading p {
    margin: 0;
}

.metric-grid {
    display: grid;
    gap: 18px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    margin-bottom: 22px;
}

.metric-card,
.panel {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 11px;
    box-shadow: var(--shadow-card);
}

.metric-card {
    display: grid;
    gap: 8px;
    min-height: 145px;
    padding: 20px;
}

.metric-label {
    color: var(--color-muted);
    font-size: 13px;
    font-weight: 650;
}

.metric-value {
    color: var(--color-ink);
    font-size: 32px;
    letter-spacing: -0.04em;
    line-height: 1;
}

.metric-note {
    font-size: 12px;
}

.content-grid {
    align-items: start;
    display: grid;
    gap: 20px;
