    margin: 0 0 3px;
}

.panel-heading .muted {
    font-size: 13px;
}

.text-link {
    font-size: 13px;
    font-weight: 650;
    white-space: nowrap;
}

.table-wrap {
    overflow-x: auto;
}

table {
    border-collapse: collapse;
