:root {
    color-scheme: light;
    --color-ink: #172b4d;
    --color-muted: #68778d;
    --color-primary: #2357a5;
    --color-primary-dark: #19427f;
    --color-canvas: #f4f7fb;
    --color-surface: #ffffff;
    --color-border: #e2e8f0;
    --color-success: #18794e;
    --color-danger: #b42318;
    --shadow-card: 0 8px 24px rgba(28, 48, 79, 0.06);
    font-family: Inter, "Segoe UI", Arial, sans-serif;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    background: var(--color-canvas);
    color: var(--color-ink);
    font-size: 15px;
    line-height: 1.5;
}

a {
    color: var(--color-primary);
    text-decoration: none;
}

a:hover {
    color: var(--color-primary-dark);
}

button,
input {
    font: inherit;
}

.app-shell {
    min-height: 100vh;
}

.topbar {
    align-items: center;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    display: flex;
    height: 68px;
    justify-content: space-between;
    padding: 0 30px;
    position: sticky;
    top: 0;
    z-index: 5;
}

.topbar-brand {
    color: var(--color-ink);
    font-size: 19px;
    font-weight: 750;
    letter-spacing: -0.03em;
}

.topbar-user,
.topbar-user form {
    align-items: center;
    display: flex;
    gap: 16px;
    margin: 0;
}

.user-name {
    color: var(--color-muted);
    font-size: 14px;
}

.menu-toggle {
    background: transparent;
    border: 0;
    color: var(--color-ink);
    cursor: pointer;
    display: none;
    font-size: 22px;
    padding: 5px;
}

.sidebar {
    background: #102b50;
    bottom: 0;
    color: #d7e3f4;
    left: 0;
    overflow-y: auto;
    padding: 26px 16px;
    position: fixed;
    top: 68px;
    width: 248px;
}

.sidebar-section-label {
    color: #a9bdd7;
    display: block;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.09em;
    margin: 0 10px 12px;
    text-transform: uppercase;
}

.sidebar nav {
    display: grid;
    gap: 5px;
}

.nav-link {
    border-radius: 7px;
    color: #e8eff9;
    display: block;
    padding: 10px 12px;
}

.nav-link:hover,
.nav-link:focus-visible {
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
}

.sidebar-note {
    border-top: 1px solid rgba(255, 255, 255, 0.16);
    display: grid;
    gap: 4px;
    margin-top: 28px;
    padding-top: 20px;
}

.sidebar-note .sidebar-section-label {
    margin-left: 0;
    margin-bottom: 0;
}

.sidebar-note strong {
    color: #ffffff;
    font-size: 14px;
    padding-left: 10px;
    text-transform: capitalize;
}

.main-content {
    margin-left: 248px;
    min-height: calc(100vh - 68px);
    padding: 34px clamp(20px, 3vw, 44px);
}

.page-heading {
    align-items: center;
    display: flex;
    justify-content: space-between;
    margin-bottom: 26px;
}

.page-heading h1,
.login-card h1 {
    font-size: clamp(26px, 3vw, 34px);
    letter-spacing: -0.04em;
    line-height: 1.2;
    margin: 3px 0 7px;
}

.eyebrow {
    color: var(--color-primary);
    font-size: 12px;
    font-weight: 750;
    letter-spacing: 0.08em;
    margin: 0;
    text-transform: uppercase;
}

.muted,
.metric-note {
    color: var(--color-muted);
}

.page-heading .muted,
.panel-heading p {
    margin: 0;
}

.metric-grid {
    display: grid;
    gap: 18px;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    margin-bottom: 22px;
}

.metric-card,
.panel {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 11px;
    box-shadow: var(--shadow-card);
}

.metric-card {
    display: grid;
    gap: 8px;
    min-height: 145px;
    padding: 20px;
}

.metric-label {
    color: var(--color-muted);
    font-size: 13px;
    font-weight: 650;
}

.metric-value {
    color: var(--color-ink);
    font-size: 32px;
    letter-spacing: -0.04em;
    line-height: 1;
}

.metric-note {
    font-size: 12px;
}

.content-grid {
    align-items: start;
    display: grid;
    gap: 20px;
    grid-template-columns: minmax(0, 1fr) minmax(230px, 300px);
}

.panel {
    padding: 22px;
}

.panel-heading {
    align-items: center;
    display: flex;
    gap: 14px;
    justify-content: space-between;
    margin-bottom: 18px;
}

.panel-heading h2,
.panel h2 {
    font-size: 17px;
    letter-spacing: -0.02em;
    margin: 0 0 3px;
}

.panel-heading .muted {
    font-size: 13px;
}

.text-link {
    font-size: 13px;
    font-weight: 650;
    white-space: nowrap;
}

.table-wrap {
    overflow-x: auto;
}

table {
    border-collapse: collapse;
    min-width: 600px;
    width: 100%;
}

th,
td {
    border-bottom: 1px solid var(--color-border);
    padding: 12px 10px;
    text-align: left;
    vertical-align: middle;
}

th {
    color: var(--color-muted);
    font-size: 11px;
    font-weight: 750;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

td {
    font-size: 13px;
}

tbody tr:last-child td {
    border-bottom: 0;
}

.badge {
    background: #edf3fb;
    border-radius: 999px;
    color: #315886;
    display: inline-block;
    font-size: 11px;
    font-weight: 650;
    margin-right: 4px;
    padding: 3px 8px;
}

.empty-state {
    color: var(--color-muted);
    padding: 24px 10px;
    text-align: center;
}

.quick-actions nav {
    display: grid;
    gap: 8px;
}

.action-link {
    align-items: center;
    border: 1px solid var(--color-border);
    border-radius: 8px;
    color: var(--color-ink);
    display: flex;
    font-size: 13px;
    font-weight: 650;
    justify-content: space-between;
    padding: 12px;
}

.action-link:hover {
    background: #f7faff;
    border-color: #b9cde8;
}

.button {
    align-items: center;
    border: 0;
    border-radius: 7px;
    cursor: pointer;
    display: inline-flex;
    font-weight: 700;
    justify-content: center;
    padding: 10px 15px;
}

.button-primary {
    background: var(--color-primary);
    color: #ffffff;
}

.button-secondary {
    background: #edf3fb;
    color: #315886;
}

.button-secondary:hover {
    background: #dce8f7;
    color: var(--color-primary-dark);
}

.export-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
}

.button-primary:hover {
    background: var(--color-primary-dark);
    color: #ffffff;
}

.button-quiet {
    background: transparent;
    color: var(--color-primary);
    padding: 8px;
}

.button-full {
    margin-top: 8px;
    width: 100%;
}

.login-page {
    align-items: center;
    display: flex;
    justify-content: center;
    min-height: 100vh;
    padding: 24px;
}

.login-card {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    box-shadow: var(--shadow-card);
    max-width: 440px;
    padding: 38px;
    width: 100%;
}

.brand-mark {
    align-items: center;
    background: #eaf1fb;
    border-radius: 10px;
    color: var(--color-primary);
    display: flex;
    font-size: 14px;
    font-weight: 800;
    height: 42px;
    justify-content: center;
    margin-bottom: 22px;
    width: 52px;
}

.login-card > .muted {
    margin: 0 0 22px;
}

.form-stack {
    display: grid;
    gap: 10px;
}

.form-stack label {
    font-size: 13px;
    font-weight: 700;
    margin-top: 5px;
}

.form-stack input {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 7px;
    min-height: 44px;
    padding: 10px 12px;
    width: 100%;
}

.form-stack input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(35, 87, 165, 0.13);
    outline: none;
}

