    border-radius: 7px;
    font-size: 13px;
    margin: 18px 0;
    padding: 11px 13px;
}

.alert-error {
    background: #fff1f0;
    border: 1px solid #f4c7c3;
    color: var(--color-danger);
}

.alert-success {
    background: #ecfdf3;
    border: 1px solid #a6f4c5;
    color: var(--color-success);
}

.data-form {
    align-items: end;
    display: grid;
    gap: 14px;
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.data-form-single {
    align-items: stretch;
