}

.form-stack {
    display: grid;
    gap: 10px;
}

.form-stack label {
    font-size: 13px;
    font-weight: 700;
    margin-top: 5px;
}

.form-stack input {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 7px;
    min-height: 44px;
    padding: 10px 12px;
    width: 100%;
}

.form-stack input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px rgba(35, 87, 165, 0.13);
    outline: none;
}

.alert {
    border-radius: 7px;
    font-size: 13px;
    margin: 18px 0;
    padding: 11px 13px;
}

.alert-error {
