    display: flex;
    flex-wrap: wrap;
    gap: 9px;
}

.button-primary:hover {
    background: var(--color-primary-dark);
    color: #ffffff;
}

.button-quiet {
    background: transparent;
    color: var(--color-primary);
    padding: 8px;
}

.button-full {
    margin-top: 8px;
    width: 100%;
}

