    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    box-shadow: var(--shadow-card);
    max-width: 440px;
    padding: 38px;
    width: 100%;
}

.brand-mark {
    align-items: center;
    background: #eaf1fb;
    border-radius: 10px;
    color: var(--color-primary);
    display: flex;
    font-size: 14px;
    font-weight: 800;
    height: 42px;
    justify-content: center;
    margin-bottom: 22px;
    width: 52px;
