}

.form-actions {
    align-self: end;
}

.table-panel .panel-heading {
    margin-bottom: 12px;
}

.inline-actions,
.row-actions {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.row-actions {
    align-items: flex-start;
    flex-direction: column;
}

.button-small {
    font-size: 12px;
    padding: 7px 10px;
}

.button-danger {
    background: #fff1f0;
    color: var(--color-danger);
}

.button-danger:hover {
    background: #fee4e2;
    color: #912018;
}

.badge-warning {
    background: #fff7e6;
    color: #8a4b08;
}

.badge-success {
    background: #ecfdf3;
    color: #166534;
}

details > summary {
    color: var(--color-primary);
    cursor: pointer;
    font-size: 12px;
    font-weight: 650;
}

.compact-form {
    background: #f8fafc;
    border: 1px solid var(--color-border);
    border-radius: 7px;
    margin-top: 8px;
    min-width: 190px;
    padding: 10px;
}

.report-note {
    border-top: 1px solid var(--color-border);
    font-size: 12px;
    margin: 18px 0 0;
    padding-top: 14px;
}

.audit-details {
    background: #f8fafc;
    border: 1px solid var(--color-border);
    border-radius: 6px;
    font-size: 11px;
    margin: 8px 0;
    max-width: 360px;
    overflow-wrap: anywhere;
    padding: 9px;
    white-space: pre-wrap;
}

.sr-only {
    clip: rect(0, 0, 0, 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

.login-help {
    color: var(--color-muted);
    font-size: 12px;
    margin: 20px 0 0;
    text-align: center;
}

@media (max-width: 1100px) {
    .metric-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .content-grid {
        grid-template-columns: 1fr;
    }

    .data-form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 760px) {
    .topbar {
        height: 60px;
        padding: 0 16px;
    }

    .menu-toggle {
        display: block;
    }

    .topbar-brand {
        margin-right: auto;
        padding-left: 10px;
    }

    .topbar-user {
        gap: 5px;
    }

    .user-name {
        display: none;
    }

    .sidebar {
        bottom: auto;
        display: none;
        max-height: calc(100vh - 60px);
        position: absolute;
        top: 60px;
        width: min(290px, 85vw);
        z-index: 4;
    }

    .sidebar.is-open {
        display: block;
    }

    .main-content {
        margin-left: 0;
        min-height: calc(100vh - 60px);
        padding: 25px 16px;
    }

    .data-form {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .metric-grid {
        gap: 12px;
        grid-template-columns: 1fr 1fr;
    }

    .metric-card {
        min-height: 132px;
        padding: 15px;
    }

    .metric-value {
        font-size: 27px;
    }

    .metric-note {
        font-size: 11px;
    }

    .panel {
        padding: 17px;
    }

    .login-card {
        padding: 28px 22px;
    }
}

